import{_ as i,o as a,c as o,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Checklist manuale — parità funzionale (M1)","description":"","frontmatter":{},"headers":[],"relativePath":"qa/parita-funzionale-m1.md","filePath":"qa/parita-funzionale-m1.md"}'),n={name:"qa/parita-funzionale-m1.md"};function r(l,e,c,s,d,u){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="checklist-manuale-—-parita-funzionale-m1" tabindex="-1">Checklist manuale — parità funzionale (M1) <a class="header-anchor" href="#checklist-manuale-—-parita-funzionale-m1" aria-label="Permalink to &quot;Checklist manuale — parità funzionale (M1)&quot;">​</a></h1><p>Da eseguire sul webview reale (macOS, Windows, Linux) con una cartella di note Markdown creata con un altro editor, senza conversioni. Gli e2e automatici (<code>yarn workspace @clarae/desktop-frontend e2e</code>) coprono i flussi principali sul mock dei binding; qui si verifica ciò che solo il webview reale mostra.</p><p>Segnare <code>[x]</code> con data e sistema operativo.</p><h2 id="apertura-vault" tabindex="-1">Apertura vault <a class="header-anchor" href="#apertura-vault" aria-label="Permalink to &quot;Apertura vault&quot;">​</a></h2><ul><li>[ ] &quot;Apri cartella come vault&quot; su una cartella di note reale creata con un altro editor: albero completo, la sua cartella nascosta di impostazioni non mostrata, nessuna modifica ai file all&#39;apertura.</li><li>[ ] Indice iniziale con barra di avanzamento in basso; dopo il termine la ricerca restituisce risultati.</li><li>[ ] Chiusura e riapertura: tab, split e barre laterali ripristinati (<code>.clarae/workspace.json</code>); un file cancellato nel frattempo non lascia tab vuote.</li></ul><h2 id="link" tabindex="-1">Link <a class="header-anchor" href="#link" aria-label="Permalink to &quot;Link&quot;">​</a></h2><ul><li>[ ] <code>[[Nota]]</code>, <code>[[Nota|alias]]</code>, <code>[[Nota#Heading]]</code>, <code>[[Nota#^blocco]]</code>, <code>[[#Heading]]</code> si risolvono come da specifica (percorso più breve, alias del frontmatter).</li><li>[ ] Link non risolto: stile &quot;fantasma&quot;; clic con ⌘/Ctrl crea la nota.</li><li>[ ] Rinomina di un file dall&#39;explorer: anteprima &quot;N link in M note&quot;, i link sono riscritti, le tab seguono il nuovo nome.</li><li>[ ] Spostamento via drag&amp;drop in una cartella: stesso comportamento.</li><li>[ ] Backlink e menzioni non collegate coerenti con i link presenti nelle note.</li></ul><h2 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to &quot;Editor&quot;">​</a></h2><ul><li>[ ] Live (editor WYSIWYG Milkdown): heading, grassetto/corsivo/barrato/evidenziato, codice inline e blocchi, citazioni, liste, task (checkbox cliccabile), tabelle, footnote, tag, commenti <code>%%</code>.</li><li>[ ] Differenza voluta rispetto agli editor a sorgente visibile (ADR-0049): in Live i simboli Markdown non riappaiono sulla riga del cursore (la nota è WYSIWYG); riappaiono per wikilink, embed e commenti <code>%%</code> quando il cursore li tocca, e in Sorgente. Frontmatter nascosto e mostrato in Properties.</li><li>[ ] Callout (tutti i tipi, titolo personalizzato, <code>+</code>/<code>-</code> ripiegabili).</li><li>[ ] Math <code>$…$</code> e <code>$$…$$</code>; diagramma mermaid; errori di sintassi mostrati senza rompere la nota.</li><li>[ ] Embed: nota intera, <code>#heading</code>, <code>#^blocco</code>, immagine con <code>|300</code> e <code>|300x200</code>, PDF <code>#page=2</code>, audio, video; embed circolare → avviso.</li><li>[ ] Autocompletamento <code>[[</code> (note, alias, <code>#heading</code>, <code>#^blocco</code>), <code>#tag</code>, nomi proprietà.</li><li>[ ] Hotkey: ⌘B/I, ⌘K, ⌘⇧K, ⌘1…6, ⌘⏎ (task), ⌘E (reading), ⌘O, ⌘P, ⌘N, ⌘\\ (split), ⌘W.</li><li>[ ] Incolla: URL su selezione → link; HTML → Markdown; immagine → allegato + <code>![[…]]</code>.</li><li>[ ] Modifica esterna mentre la nota è aperta: senza modifiche locali si aggiorna; con modifiche locali compare il banner Ricarica/Sovrascrivi.</li><li>[ ] Digitazione fluida (nessun lag percepibile) su una nota da ~1 MB: oltre 250.000 caratteri la nota si apre in Sorgente (con avviso), quindi la prova va fatta in Sorgente; in Live provare una nota di 200 kB (apertura attesa circa 2,5 s in Chromium headless, da confermare sulla webview reale).</li></ul><h2 id="reading-view" tabindex="-1">Reading view <a class="header-anchor" href="#reading-view" aria-label="Permalink to &quot;Reading view&quot;">​</a></h2><ul><li>[ ] Resa equivalente alla Live Preview; wikilink e tag cliccabili; callout, task con stati personalizzati; HTML pericoloso (<code>&lt;script&gt;</code>, <code>onerror</code>) non eseguito.</li></ul><h2 id="properties-tag-outline" tabindex="-1">Properties, tag, outline <a class="header-anchor" href="#properties-tag-outline" aria-label="Permalink to &quot;Properties, tag, outline&quot;">​</a></h2><ul><li>[ ] Properties tipizzate (testo, lista, numero, casella, data, data/ora): modifica riscrive il frontmatter preservando ordine e commenti.</li><li>[ ] Vista Tags gerarchica con conteggi; clic filtra la ricerca. Outline segue i titoli e porta alla riga.</li><li>[ ] Barra di stato (facoltativa, spenta per default, ADR-0035): parole, caratteri, selezione, riga:colonna, modalità; spenta, gli stessi conteggi sono nella scheda <em>Statistiche</em>.</li></ul><h2 id="workspace-e-impostazioni" tabindex="-1">Workspace e impostazioni <a class="header-anchor" href="#workspace-e-impostazioni" aria-label="Permalink to &quot;Workspace e impostazioni&quot;">​</a></h2><ul><li>[ ] Split orizzontale/verticale, trascinamento tab tra pannelli, pannelli collegati, ridimensionamento.</li><li>[ ] Palette comandi, selettore rapido (⌘⏎ nuova tab, crea se manca).</li><li>[ ] Impostazioni: editor, file e link, aspetto, hotkey (registrazione, conflitti, ripristino), cloud, informazioni; <code>clarae://open?vault=&amp;file=</code> apre la nota.</li></ul><h2 id="limiti-noti" tabindex="-1">Limiti noti <a class="header-anchor" href="#limiti-noti" aria-label="Permalink to &quot;Limiti noti&quot;">​</a></h2><ul><li>Ricerca su vault da 50k note: risolto in M7-WP1 con la cache dei candidati (ADR-0020): 0,03-0,14 s misurati; le regex sull&#39;intero vault restano ≈ 0,45 s (<code>docs/perf/README.md</code>).</li></ul><h2 id="m6-—-funzioni-p1-residue" tabindex="-1">M6 — funzioni P1 residue <a class="header-anchor" href="#m6-—-funzioni-p1-residue" aria-label="Permalink to &quot;M6 — funzioni P1 residue&quot;">​</a></h2><p>Da eseguire sul webview reale (le parti automatiche sono coperte da Vitest, Go e Playwright sul mock).</p><ul><li>[ ] <strong>Grafo</strong> (⌘⇧G): globale e locale (pulsante nei backlink); filtri, gruppi colore per query, forze, timelapse; click apre la nota, ⌘/Ctrl-click in nuova tab, nodo fantasma crea la nota; su un vault da 10k note pan/zoom fluidi e ≥ 30 fps (annotare macchina e webview: la misura headless è in <code>docs/qa/m6-graph-benchmark.md</code>).</li><li>[ ] <strong>Bases</strong>: nuova base dal menu cartella; viste tabella/card, ordinamento, raggruppamento, filtro semplice, modifica inline di una property (il frontmatter cambia, il resto della nota no); <code>![[x.base#Vista]]</code> in Live Preview e Reading; un <code>.base</code> creato da un altro editor con chiavi sconosciute resta intatto dopo una modifica.</li><li>[ ] <strong>Daily/unique note</strong>: &quot;Apri nota di oggi&quot; crea dal template, giorno precedente/successivo; formato con <code>/</code> crea sottocartelle; unique note con prefisso timestamp.</li><li>[ ] <strong>Template</strong>: inserisci template con <code>{{date:FORMAT}}</code>, <code>{{time}}</code>, <code>{{title}}</code>; con la libreria di gruppo montata compaiono anche i template di gruppo (sola lettura).</li><li>[ ] <strong>Composer</strong>: unisci note (anteprima &quot;N link in M note&quot;, link reindirizzati, sorgente nel cestino); estrai selezione in nuova nota sostituendola con <code>[[link]]</code>.</li><li>[ ] <strong>Slash <code>/</code></strong> in una riga vuota apre il menu; non compare in codice, frontmatter, URL; si disattiva nelle impostazioni. <strong>Nota casuale</strong> non riapre la corrente.</li><li>[ ] <strong>Bookmarks</strong>: nota, heading, blocco, ricerca, gruppi con trascinamento; rinominare un file aggiorna il segnalibro; un file cancellato resta barrato; <code>.clarae/bookmarks.json</code> si sincronizza, <code>workspaces.json</code> no.</li><li>[ ] <strong>Workspaces</strong>: salva, carica (le modifiche non salvate vengono scritte prima), elimina; le tab di file inesistenti vengono scartate.</li><li>[ ] <strong>Page preview</strong>: ⌘/Ctrl + passaggio sul wikilink (o sempre, da impostazione) mostra l&#39;anteprima di nota/heading/blocco; Esc chiude; nessun contenuto remoto.</li><li>[ ] <strong>Importer</strong> (wizard &quot;Importa…&quot;): una cartella Markdown, un ENEX, uno zip Notion, un JSON Roam, un Bear, un Takeout Keep, un CSV — <strong>con export reali</strong>, annotando differenze rispetto ai fixture; il report finale e la nota &quot;Import report&quot; sono corretti; nessun file esistente viene sovrascritto.</li><li>[ ] <strong>File recovery</strong>: modifica una nota, attendi lo snapshot (5 min o riducilo), apri &quot;File recovery&quot;: versioni locali (e cloud se collegato) con diff; ripristina; &quot;Recupera file eliminati&quot;.</li><li>[ ] <strong>Blocco ```query</strong>: risultati live in Live Preview e Reading, errore inline, &quot;mostra altri&quot;.</li><li>[ ] <strong>Export HTML/PDF</strong>: l&#39;HTML si apre offline, senza script né risorse remote; il PDF dal dialogo di stampa del sistema su macOS, Windows e Linux (limiti in ADR-0019).</li></ul><h2 id="disegni-parita-con-i-plugin-excalidraw-di-terze-parti-adr-0024" tabindex="-1">Disegni: parità con i plugin Excalidraw di terze parti (ADR-0024) <a class="header-anchor" href="#disegni-parita-con-i-plugin-excalidraw-di-terze-parti-adr-0024" aria-label="Permalink to &quot;Disegni: parità con i plugin Excalidraw di terze parti (ADR-0024)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Funzione del plugin</th><th>Stato</th></tr></thead><tbody><tr><td>Formato <code>.excalidraw</code> in chiaro, link agli elementi, embed di parti, allineamento</td><td>fatto</td></tr><tr><td>Esportazione PNG/SVG (selezione, cornice, scala, scena incorporata), PDF, auto-export</td><td>fatto</td></tr><tr><td>Inserimento di immagini, note e disegni; trascinamento dal vault</td><td>fatto (le note sono schede, non snapshot SVG)</td></tr><tr><td>LaTeX (MathJax), Mermaid</td><td>fatto, offline</td></tr><tr><td>Presentazione a diapositive, note del relatore, laser, penne</td><td>fatto</td></tr><tr><td>Script Library: layout, colore/stile, forme, frecce, testo, generatori, mappa mentale, calendari</td><td>fatto come azioni native (niente script utente, V-02/D-01)</td></tr><tr><td>Import <code>.excalidraw.md</code> e <code>.excalidrawlib</code></td><td>fatto (le formule LaTeX diventano immagini con il TeX in <code>customData</code>; l&#39;editor le disegna all&#39;apertura)</td></tr><tr><td>Icon Library, Image Occlusion, LayerManager, Crop Vintage Mask, Capture Note, Folder Note, &quot;Fixed inner distance&quot;</td><td>non implementati nella 1.0.0</td></tr><tr><td>Collaboration Frame</td><td>escluso (D-04: niente collaborazione in tempo reale)</td></tr><tr><td>Scribble Helper, Hardware Eraser / Auto Draw for Pen</td><td>esclusi (richiedono una penna fisica)</td></tr><tr><td>ExcaliAI, OCR, miniature YouTube, immagini da URL, Script Library da GitHub</td><td>esclusi (rete: ADR-0005)</td></tr><tr><td>Modalità per mancini</td><td>non disponibile in Excalidraw 0.18</td></tr></tbody></table><h2 id="limiti-noti-aggiornati" tabindex="-1">Limiti noti (aggiornati) <a class="header-anchor" href="#limiti-noti-aggiornati" aria-label="Permalink to &quot;Limiti noti (aggiornati)&quot;">​</a></h2><ul><li>Embed <code>![[x.canvas]]</code> ed <code>.excalidraw</code> come in M3; <code>.base</code> ora supportato (sottoinsieme in ADR-0014).</li><li>Il grafo usa Canvas 2D; se un portatile datato scende sotto 30 fps a 10k nodi la via di riserva è pixi.js (ADR-0013).</li></ul>',24)])])}const g=i(n,[["render",r]]);export{m as __pageData,g as default};
